// ----------------------------------------------------------------------------
// TableFunctionPlanRequest  (schema: TableFunctionPlanRequestSchema)
// ----------------------------------------------------------------------------

/** Request for the scan-planning phase that precedes per-split `init()`. `plan()` runs once with the pushdown filters and returns named splits; each split is then redeemed by `init()` from any process or host. This is what makes the scan sound in a distributed engine, where a retried task must be able to re-request exactly the work it was given. */
export interface TableFunctionPlanRequest {
  /** The originating `BindRequest`. */
  bind_call: Nested<BindRequest>;
  /** Opaque per-bind state the worker returned from bind(). */
  bind_opaque_data?: Uint8Array | null;
  /** Column indices the client wants projected. */
  projection_ids?: number[] | null;
  /** Serialized filter predicates. */
  pushdown_filters?: Uint8Array | null;
  /** Serialized join-key batches pushed down for join filtering. */
  join_keys?: Uint8Array[] | null;
  /** Plain fetch limit. NOT `order_by_limit` (which is a field of the Top-N hint). DuckDB cannot supply this — `TableFunctionInitInput` has no limit field — so it is always `None` from DuckDB; DataFusion supplies it from `TableProvider::scan(limit)`. */
  row_limit?: number | null;
  /** Requested split size. The primary sizing lever: a worker should emit splits of comparable cost, because the client cannot see per-split cost and will claim them as interchangeable units. */
  target_split_bytes?: number | null;
  /** Parallelism floor — a small but expensive table still needs enough splits to occupy the client's readers. */
  min_splits?: number | null;
  /** Pagination cap (Trino `getNextBatch(maxSize)`), NOT a sizing hint. */
  max_splits_per_response?: number | null;
  /** Resume point in the *enumeration of splits*. Distinct from `start_position`, which names a place in the *data*. */
  cursor?: Uint8Array | null;
  /** Conjunctive narrowing on a continuation. Narrows future splits only; splits already emitted under a looser filter stay valid. */
  refined_filters?: Uint8Array | null;
  /** False means more refinement may arrive, so the worker may hold back splits; True says stop waiting. */
  filters_complete: boolean;
  /** Exclusive lower bound in the data; `None` = from the start. */
  start_position?: Uint8Array | null;
  /** Inclusive upper bound; `None` = "as of now", and the worker reports the frontier it resolved in `PlanResponse.end_position`. */
  end_position?: Uint8Array | null;
  /** Column of the order-pushdown hint. */
  order_by_column_name?: string | null;
  /** Direction of the order-pushdown hint. */
  order_by_direction?: string | null;
  /** Null ordering of the order-pushdown hint. */
  order_by_null_order?: string | null;
  /** Row limit of the Top-N order-pushdown hint. */
  order_by_limit?: number | null;
  /** TABLESAMPLE percentage hint. */
  tablesample_percentage?: number | null;
  /** TABLESAMPLE seed hint. */
  tablesample_seed?: number | null;
}

